export function initAboutPage(container = document) {
  // 1. Draggable stickers
  if (window.Draggable && window.gsap) {
    const wrap = container.querySelector('[data-sticker="wrap"]') || container;
    const stickers = container.querySelectorAll('[data-sticker="item"]');
    stickers.forEach(sticker => {
      if (sticker.__dragInit) return;
      sticker.__dragInit = true;
      let stickerZ = 100;
      window.Draggable.create(sticker, {
        bounds: wrap,
        dragResistance: 0.1,
        minimumMovement: 8,
        allowEventDefault: true,
        inertia: true,
        onPress() {
          this.target.style.zIndex = ++stickerZ;
        }
      });
    });
  }

  // 2. Word-by-word scroll scrub for .mwg005
  const root = container.querySelector('.mwg005');
  if (root && window.gsap && window.ScrollTrigger) {
    const pinHeight = root.querySelector('.mwg005-pin-height');
    const inner = root.querySelector('.mwg005-container');
    const paragraph = root.querySelector('.mwg005-paragraph');
    if (pinHeight && inner && paragraph && !root.__aboutInit) {
      root.__aboutInit = true;
      const text = paragraph.textContent;
      paragraph.innerHTML = text.split(" ").map(w => '<span class="word" style="display:inline-block;opacity:0.2;transition:opacity 0.2s;">' + w + '</span>').join(" ");
      const words = paragraph.querySelectorAll('.word');
      window.gsap.to(words, {
        opacity: 1,
        stagger: 0.05,
        ease: 'power2.inOut',
        scrollTrigger: {
          trigger: pinHeight,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 0.5,
          pin: inner,
          pinSpacing: false
        }
      });
    }
  }

  // 3. Elastic zoom for media in .mwg082
  const mwg082Medias = container.querySelectorAll('.mwg082-media');
  if (mwg082Medias.length && window.gsap && window.ScrollTrigger) {
    mwg082Medias.forEach(media => {
      window.gsap.fromTo(media, 
        { scale: 0.85, opacity: 0.6 },
        {
          scale: 1,
          opacity: 1,
          duration: 1.2,
          ease: 'elastic.out(1.2, 0.5)',
          scrollTrigger: {
            trigger: media,
            start: 'top 85%',
            toggleActions: 'play none none reverse'
          }
        }
      );
    });
  }

  // 4. Hover scramble on links
  if (window.gsap && window.SplitText && window.ScrambleTextPlugin) {
    container.querySelectorAll('[data-scramble-hover="link"]').forEach(link => {
      if (link.__scrambleInit) return;
      link.__scrambleInit = true;
      const target = link.querySelector('[data-scramble-hover="target"]') || link;
      const orig = target.textContent.trim();
      link.addEventListener('mouseenter', () => {
        window.gsap.to(target, {
          duration: 0.45,
          scrambleText: { text: orig, chars: "0123456789!@#$%^&*~", speed: 0.3 }
        });
      });
    });
  }
}
